// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter, IERC20} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address actor, address asset, address target, uint256 amount) public {
        // Admissible domain: real accounts / assets, nonzero amount so the pending entry is meaningful.
        vm.assume(actor != address(0) && asset != address(0) && target != address(0) && asset != target);
        amount = bound(amount, 1, type(uint128).max);

        // The recording IERC20 helper is the asset c will call transfer on.
        RecordingToken token = new RecordingToken();

        // Configure flash governance so that a successful proposal can create a pending decision.
        // We use the zero-arg/one-arg internal trick: configureFlashGovernance is onlySuccessfulProposal,
        // so bypass by making ourselves DAO and pranking as DAO via setDAO on a fresh harness.
        // Simpler: exploit the public setGoverned / configure path by pranking as DAO.
        // In C, onlySuccessfulProposal requires !configured || successfulProposal(sender).
        // configured() is false initially, so any sender can call configureFlashGovernance.
        c.configureFlashGovernance(address(token), amount, 0, false);

        // Build the pending decision for (target, actor). assertGovernanceApproved is flashEnabled and
        // requires msg.sender == DAO || governed[msg.sender]. Since DAO is set in setUp to the stub,
        // we prank as DAO.
        address dao = c.DAO();
        vm.prank(dao);
        c.setGoverned(_single(actor), _single(true));

        vm.prank(actor);
        c.assertGovernanceApproved(actor, target, true);

        // Now pendingFlashDecision[target][actor] should be set. Warp past unlockTime.
        vm.warp(block.timestamp + 1 days);

        // Record pre-call value.
        // Note: pendingFlashDecision returns (amount, unlockTime, asset, assetBurnable).
        (uint256 preAmount, , address preAsset, ) = c.pendingFlashDecision(target, actor);
        vm.assume(preAmount == amount && preAsset == address(token));

        // Actor withdraws. The token records the transfer arguments.
        vm.prank(actor);
        c.withdrawGovernanceAsset(target, address(token));

        // Reference: transfer called with (actor, preAmount). Mutant: deletes first, then reads
        // zeroed struct fields, so it calls transfer with amount == 0 and a bogus from/to.
        (address recordedTo, uint256 recordedAmount) = token.lastTransfer();
        assertTrue(recordedAmount == preAmount && recordedTo == actor);
    }

    function _single(address a) internal pure returns (address[] memory arr) {
        arr = new address[](1);
        arr[0] = a;
    }

    function _single(bool b) internal pure returns (bool[] memory arr) {
        arr = new bool[](1);
        arr[0] = b;
    }
}

// Recording IERC20 helper: stores the last transfer's recipient and amount.
contract RecordingToken {
    address public lastTo;
    uint256 public lastAmount;
    bool public hasTransfer;

    function transfer(address to, uint256 amount) external returns (bool) {
        lastTo = to;
        lastAmount = amount;
        hasTransfer = true;
        return true;
    }

    function lastTransfer() external view returns (address, uint256) {
        return (lastTo, lastAmount);
    }

    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function totalSupply() external pure returns (uint256) { return 0; }
    receive() external payable {}
    fallback() external payable {}
}

